-- =============================================================================
-- Macheo Ecolodge & Camping — seed data (generated by scripts/generate-seed.mjs)
-- =============================================================================
-- Run AFTER the migrations. Everything here is upsert-safe.
--
-- ⚠ DEMO contact values (phone / WhatsApp / email) are placeholders so a
--   fresh database is browsable. Replace them in Admin → Contact information
--   with the confirmed numbers before the site is shared publicly.
--   Demo rooms, tents and experiences are seeded UNPUBLISHED where possible;
--   nothing invented reaches guests until an admin publishes it.
-- =============================================================================

-- site_settings
insert into public.site_settings (id, site_title, meta_description)
values (
  1,
  'Macheo Ecolodge & Camping | Stay, Camp & Explore Lake Kivu',
  'Macheo Ecolodge & Camping in Karongi (Kibuye), Rwanda — rooms, camping, a restaurant and bar, and lake experiences on the shores of Lake Kivu.'
)
on conflict (id) do update
  set site_title = excluded.site_title,
      meta_description = excluded.meta_description;

-- business_info (DEMO contact values — see header)
insert into public.business_info (
  id, name, tagline, street, city, country, phone, whatsapp, email,
  directions_url, opening_hours
)
values (
  1,
  'Macheo Ecolodge & Camping',
  'Stay closer to nature. Experience Lake Kivu.',
  null,
  'Karongi (Kibuye)',
  'Rwanda',
  '+250788000111',
  '+250788000111',
  'hello@macheo.example',
  null,
  '[]'::jsonb
)
on conflict (id) do update
  set name = excluded.name,
      tagline = excluded.tagline,
      city = excluded.city,
      country = excluded.country,
      phone = excluded.phone,
      whatsapp = excluded.whatsapp,
      email = excluded.email;

-- site_content (one row; NULL fields fall back to built-in defaults)
insert into public.site_content (id)
values (1)
on conflict (id) do nothing;

-- hero_media — the bundled photograph as the active hero image
insert into public.hero_media (title, subtitle, video_url, poster_url, is_active)
select
  'Macheo Ecolodge & Camping',
  'Stay closer to nature. Experience Lake Kivu.',
  null,
  '/images/macheo/hero-lake.jpg',
  true
where not exists (select 1 from public.hero_media where is_active);

