-- menu — demo structure from data/menu.ts (no prices)
insert into public.menu_categories (slug, name, intro, sort_order, published)
values ('food', 'Food', 'Fresh, lake-side cooking — breakfast, lunch and dinner.', 0, true)
on conflict (slug) do nothing;

insert into public.menu_sections (category_id, title, note, sort_order)
select c.id, null, null, 1
from public.menu_categories c
where c.slug = 'food'
  and not exists (
    select 1 from public.menu_sections s
    where s.category_id = c.id and s.title is not distinct from null
  );

insert into public.menu_items (section_id, name, description, price, dietary, variants, availability_note, available, sort_order)
select s.id, 'Breakfast Plates', 'Fruit, eggs, toast and local honey — a slow start with lake views.', null,
       '{}', '[]'::jsonb,
       null, true, 0
from public.menu_sections s
join public.menu_categories c on c.id = s.category_id
where c.slug = 'food'
  and s.title is not distinct from null
  and not exists (
    select 1 from public.menu_items i where i.section_id = s.id and i.name = 'Breakfast Plates'
  );

